impl Solution {
    pub fn generate_parenthesis(n: i32) -> Vec<String> {
        let mut res = vec![];

        fn valid(s: &str) -> bool {
            let mut open = 0i32;
            for c in s.chars() {
                open += if c == '(' { 1 } else { -1 };
                if open < 0 {
                    return false;
                }
            }
            open == 0
        }

        fn dfs(s: String, n: i32, res: &mut Vec<String>) {
            if s.len() == (n * 2) as usize {
                if valid(&s) {
                    res.push(s);
                }
                return;
            }
            dfs(s.clone() + "(", n, res);
            dfs(s + ")", n, res);
        }

        dfs(String::new(), n, &mut res);
        res
