impl Solution {
    pub fn generate_parenthesis(n: i32) -> Vec<String> {
        let n = n as usize;
        let mut res: Vec<Vec<String>> = vec![vec![]; n + 1];
        res[0] = vec![String::new()];

        for k in 1..=n {
            let mut cur = vec![];
            for i in 0..k {
                let left = res[i].clone();
                let right = res[k - i - 1].clone();
                for l in &left {
                    for r in &right {
                        cur.push(format!("({}){}", l, r));
                    }
                }
            }
            res[k] = cur;
        }

        res[n].clone()
    }
}
