    }

    private void Backtrack(int n, int openN, int closedN, string current, List<string> res) {
        if (openN == closedN && openN == n) {
            res.Add(current);
            return;
        }

        if (openN < n) {
            Backtrack(n, openN + 1, closedN, current + "(", res);
        }
        if (closedN < openN) {
            Backtrack(n, openN, closedN + 1, current + ")", res);
        }
    }
}

